import{_ as s,c as a,o as t,ag as n}from"./chunks/framework.DCv_I274.js";const h=JSON.parse('{"title":"Request lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/request-lifecycle.md","filePath":"architecture/request-lifecycle.md","lastUpdated":null}'),r={name:"architecture/request-lifecycle.md"};function o(l,e,p,i,d,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h1><p>What happens to <code>PATCH /api/v1/user-groups/5</code>, from the network to the JSON response.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP request</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>routes/api.php ─► routes/v1/modules/userGroup.php        (route match)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Middleware</span></span>
<span class="line"><span>   ├─ ErrorLogMiddleware        (api group: logs any 5xx to the activity log)</span></span>
<span class="line"><span>   ├─ auth:api                  (JwtGuard: Bearer token -&gt; $request-&gt;user(), 401 if invalid)</span></span>
<span class="line"><span>   └─ module.permission:User Group Management,Update     (403 if the user&#39;s group lacks it)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>FormRequest  UserGroupRequest    (rules(); 422 {success:false,message} on failure)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Controller   UserGroupController::updateUserGroup()</span></span>
<span class="line"><span>   │   merges route params into the validated data, calls the service</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Service      UserGroupService::updateUserGroupService()</span></span>
<span class="line"><span>   │   findOrFail, fill, save, ActivityLogHelper::log(...)</span></span>
<span class="line"><span>   │   returns (object){ success, message }</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Controller   wraps it: new GlobalResponseResource($response)</span></span>
<span class="line"><span>   │   catches ModelNotFoundException -&gt; 404, InvalidException -&gt; 400, Exception -&gt; 500</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>JSON  {&quot;success&quot;: true, &quot;message&quot;: &quot;User group &#39;HR&#39; (ID: #5) updated successfully!&quot;}</span></span></code></pre></div><h2 id="who-does-what" tabindex="-1">Who does what <a class="header-anchor" href="#who-does-what" aria-label="Permalink to &quot;Who does what&quot;">​</a></h2><p><strong>Middleware</strong> decides <em>whether</em> the request may run. It never changes data.</p><p><strong>FormRequest</strong> decides whether the <em>input</em> is acceptable. It runs before the controller method, so the controller only ever sees valid data through <code>$request-&gt;validated()</code>.</p><p><strong>Controller</strong> is a translator between HTTP and the service:</p><ul><li>takes validated input plus route parameters,</li><li>calls one service method,</li><li>turns the result into a resource or JSON,</li><li>turns exceptions into status codes.</li></ul><p><strong>Service</strong> is where the work happens: queries, rules (&quot;a user can only belong to one group&quot;), transactions, logging. Services never touch HTTP details such as headers, cookies or status codes. That keeps them callable from commands, jobs and tests.</p><p><strong>Resource</strong> decides what a model looks like in JSON. It is the only place that knows the response field names.</p><h2 id="where-each-failure-is-handled" tabindex="-1">Where each failure is handled <a class="header-anchor" href="#where-each-failure-is-handled" aria-label="Permalink to &quot;Where each failure is handled&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Where it is caught</th><th>Status</th></tr></thead><tbody><tr><td>Missing / invalid / revoked access token</td><td><code>auth:api</code></td><td>401</td></tr><tr><td>Wrong role</td><td><code>role:</code> middleware</td><td>403</td></tr><tr><td>Missing module permission</td><td><code>module.permission</code></td><td>403</td></tr><tr><td>Invalid input</td><td>FormRequest <code>failedValidation()</code></td><td>422</td></tr><tr><td>Business rule broken (<code>InvalidException</code>)</td><td>Controller <code>catch</code></td><td>400</td></tr><tr><td>Record not found (<code>ModelNotFoundException</code>)</td><td>Controller <code>catch</code></td><td>404</td></tr><tr><td>Anything else</td><td>Controller <code>catch (\\Exception)</code> + <code>ErrorLogMiddleware</code></td><td>500</td></tr></tbody></table><p>Details and response shapes: <a href="/architecture/responses-and-errors">Responses &amp; errors</a>.</p>`,13)])])}const g=s(r,[["render",o]]);export{h as __pageData,g as default};
